custom_fields.clock:
[[[
  const d = new Date();
  const s = d.getHours()%12*3600 + d.getMinutes()*60 + d.getSeconds() + d.getMilliseconds()/1000;
  let marks = '';
  for (let i = 0; i < 60; i++) {
    const a = i*Math.PI/30, big = i%5===0, r1 = big ? 43 : 45, r2 = 47.5;
    marks += `<line x1="${50+r1*Math.sin(a)}" y1="${50-r1*Math.cos(a)}" x2="${50+r2*Math.sin(a)}" y2="${50-r2*Math.cos(a)}" stroke="#fff" stroke-opacity="${big?0.9:0.45}" stroke-width="${big?1.4:0.7}" stroke-linecap="round"/>`;
  }
  let nums = '';
  for (let h = 1; h <= 12; h++) {
    const a = h*Math.PI/6, r = 35.5;
    nums += `<text x="${50+r*Math.sin(a)}" y="${50-r*Math.cos(a)}" text-anchor="middle" dominant-baseline="central" fill="#fff" font-size="11" font-weight="500">${h}</text>`;
  }
  const hand = (len, w, col, period, extra) =>
    `<line x1="50" y1="${50+extra}" x2="50" y2="${50-len}" stroke="${col}" stroke-width="${w}" stroke-linecap="round"
      style="transform-origin:50px 50px;animation:hwspin ${period}s linear infinite;animation-delay:-${s % period}s"/>`;
  return `<svg viewBox="0 0 100 100" style="width:100%;height:100%;font-family:ui-rounded, 'SF Pro Rounded', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Roboto, sans-serif">
    <style>@keyframes hwspin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}</style>
    ${marks}
    ${nums}
    ${hand(22, 3.6, '#fff', 43200, 0)}
    ${hand(37, 2.6, '#fff', 3600, 0)}
    ${hand(42, 1.2, '#FFD60A', 60, 8)}
    <circle cx="50" cy="50" r="2.6" fill="#fff"/><circle cx="50" cy="50" r="1.2" fill="#FFD60A"/></svg>`;
]]]

custom_fields.now:
[[[
  if (!entity || entity.state === 'unavailable') return '<div style="opacity:.7">Meteo non disponibile</div>';
  const NWS = 'weather.home';
  window.__hwNws = window.__hwNws || {};
  const F = window.__hwNws;
  if (!F.busy && hass && (!F.next || Date.now() >= F.next)) {
    F.busy = true;
    Promise.resolve().then(() => hass.callService('weather', 'get_forecasts', {type: 'daily'}, {entity_id: NWS}, false, true))
      .then((r) => {
        const resp = (r && r.response) ? r.response[NWS] : null;
        if (resp && resp.forecast) { F.td = resp.forecast.flatMap(p => [Object.assign({}, p, {is_daytime: true}), Object.assign({}, p, {is_daytime: false, temperature: (p.templow != null ? p.templow : p.temperature)})]); F.err = null; } else { F.err = 'no forecast in response'; }
        F.next = Date.now() + (F.err ? 60000 : 1800000);
