  const dayP = td.find(p => p.is_daytime);
  const nightP = td.find(p => !p.is_daytime);
  const hi = dayP && dayP.temperature != null ? Math.round(dayP.temperature) + '\u00b0' : '\u2013';
  const lo = nightP && nightP.temperature != null ? Math.round(nightP.temperature) + '\u00b0' : '\u2013';
  const pops = td.slice(0, 2).map(p => p.precipitation_probability).filter(v => v != null);
  const pop = pops.length ? Math.max(...pops) + '%' : '\u2013';
  const hlErr = (!td.length && F.err) ? `<div style="font-size:12px;opacity:.75">Previsioni non disponibili: ${F.err}</div>` : '';
  const st = entity.state;
  const label = NAMES[st] || (st.charAt(0).toUpperCase() + st.slice(1));
  const t = Math.round(entity.attributes.temperature);
  const now = new Date();
  const time = now.toLocaleTimeString('it-IT', {hour:'numeric', minute:'2-digit'});
  const date = now.toLocaleDateString('it-IT', {weekday:'long', month:'short', day:'numeric'});
  const big = String(t).length >= 3 ? 150 : 200;
  return `<div style="display:flex;flex-direction:column;height:100%;box-sizing:border-box">
   <div style="display:flex;justify-content:space-between;align-items:baseline;width:100%">
     <span style="font-size:22px;font-weight:600">${time}</span>
     <span style="font-size:15px;opacity:.8">${date}</span>
   </div>
   <div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:0">
     <span style="font-size:${big}px;font-weight:500;font-family:ui-rounded, 'SF Pro Rounded', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Roboto, sans-serif;line-height:.85;letter-spacing:-0.04em;padding-left:0.12em">${t}\u00b0</span>
     <span style="display:flex;align-items:center;gap:8px"><ha-icon icon="${ICONS[st]||'mdi:weather-partly-cloudy'}" style="--mdc-icon-size:34px"></ha-icon><span style="font-size:24px;font-weight:600">${label}</span></span>
   </div>
   <div>
     <div style="display:flex;align-items:center;justify-content:center;gap:14px;border-top:0.5px solid rgba(255,255,255,0.35);padding-top:12px;font-size:22px;font-weight:500;font-family:ui-rounded, 'SF Pro Rounded', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Roboto, sans-serif;white-space:nowrap">
       <span>H: ${hi}</span><span style="width:0;height:22px;border-left:0.5px solid rgba(255,255,255,0.35)"></span><span style="opacity:.85">L: ${lo}</span><span style="width:0;height:22px;border-left:0.5px solid rgba(255,255,255,0.35)"></span>
       <span style="display:flex;align-items:center;gap:4px"><ha-icon icon="mdi:water-outline" style="--mdc-icon-size:22px"></ha-icon>${pop}</span>
     </div>
     <div style="text-align:center">${hlErr}</div>
   </div>
  </div>`;
]]]

