        <text x="60" y="42" text-anchor="middle" fill="rgba(28,28,30,0.75)" font-size="11">${hrs}h ${mins}m</text>
      </svg>
      <div style="display:flex;flex-direction:column;align-items:center;gap:2px">
        <ha-icon icon="mdi:weather-sunset-down" style="--mdc-icon-size:28px;color:#D9620B"></ha-icon>
