  const hrsData = (F.h || []).filter(p => new Date(p.datetime).getTime() > now.getTime() - 3600000).slice(0, 12);
  let chart;
  if (hrsData.length < 2) {
    chart = `<div style="opacity:.8;font-size:15px;padding:20px 0;text-align:center">${F.err ? 'Previsioni non disponibili: ' + F.err : 'Loading forecast\u2026'}</div>`;
  } else {
    const T = hrsData.map(p => p.temperature), P = hrsData.map(p => p.precipitation_probability || 0);
    const n = T.length, W = 300, x = (i) => 14 + i * ((W - 28) / (n - 1));
    const mn = Math.min(...T) - 3, mx = Math.max(...T) + 3, y = (t) => 18 + (mx - t) / ((mx - mn) || 1) * 62;
    let o = '';
    P.forEach((v, i) => { const h = v / 100 * 62; if (h > 0) o += `<rect x="${(x(i) - 7).toFixed(1)}" y="${(80 - h).toFixed(1)}" width="14" height="${h.toFixed(1)}" rx="2" fill="rgba(0,122,255,0.55)"/>`; });
    o += `<line x1="4" y1="80" x2="${W - 4}" y2="80" stroke="rgba(0,0,0,0.18)" stroke-width="0.6"/>`;
