  };
  const esc = (t) => String(t || '').trim().replace(/[&<>"]/g, (c) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
  const dot = (e, sz) => `<span style="display:inline-block;width:${sz}px;height:${sz}px;border-radius:50%;background:${(CALS[e._cal] || {}).color || '#FFFFFF'};flex-shrink:0;vertical-align:middle;margin-right:6px"></span>`;
  const evs = (F.ev || []).filter(e => pd(e.end) > now).sort((a, b) => pd(a.start) - pd(b.start));

  const badge = (e) => {
    const s = pd(e.start), sd = startOfDay(s < now ? now : s);
    const isToday = sd.getTime() === today.getTime();
    const wd = isToday ? 'OGGI' : sd.toLocaleDateString('it-IT', {weekday: 'short'}).toUpperCase();
    return `<div style="width:54px;height:56px;border-radius:12px;background:${isToday ? 'rgba(255,255,255,0.30)' : 'rgba(255,255,255,0.14)'};border:0.5px solid rgba(255,255,255,0.40);box-shadow:inset 1px 1px 0 rgba(255,255,255,0.30);color:#FFFFFF;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0">
        <span style="font-size:12px;font-weight:600;color:${isToday ? '#FFFFFF' : 'rgba(235,235,245,0.9)'};letter-spacing:.04em;line-height:1.2">${wd}</span>
        <span style="font-size:24px;font-weight:600;line-height:1;font-family:ui-rounded, 'SF Pro Rounded', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Roboto, sans-serif;">${sd.getDate()}</span></div>`;
  };
