  else if (!evs.length) body = `<div style="font-size:17px;opacity:.85;padding-left:16px">Nessun impegno questa settimana</div>`;
  else body = evs.slice(0, 3).map(e => {
      const isToday = startOfDay(pd(e.start) < now ? now : pd(e.start)).getTime() === today.getTime();
      return `<div style="flex:1;display:flex;align-items:center;gap:12px;min-width:0;padding:6px 10px 6px 16px;border-left:0.5px solid rgba(255,255,255,0.3);${isToday ? 'background:rgba(255,255,255,0.10);border-radius:12px;' : ''}">
        ${badge(e)}
        <div style="min-width:0;text-align:left">
          <div style="font-size:18px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(e.summary)}</div>
          <div style="font-size:15px;color:rgba(235,235,245,0.85);margin-top:2px;white-space:nowrap">${dot(e, 9)}${range(e)}</div>
