custom_fields.clock:
[[[
  const d = new Date();
  const s = d.getHours() % 12 * 3600 + d.getMinutes() * 60 + d.getSeconds() + d.getMilliseconds() / 1000;
  const P = (deg, r) => { const a = deg * Math.PI / 180; return [(50 + r * Math.sin(a)).toFixed(2), (50 - r * Math.cos(a)).toFixed(2)]; };
  let marks = '';
  for (let i = 0; i < 60; i++) {
    const big = i % 5 === 0, a = P(i * 6, big ? 42.5 : 45), b = P(i * 6, 48);
    marks += `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#0B0B0C" stroke-opacity="${big ? 0.9 : 0.4}" stroke-width="${big ? 1.2 : 0.5}" stroke-linecap="round"/>`;
  }
  let nums = '';
  for (let h = 1; h <= 12; h++) {
    const p = P(h * 30, 35.5);
    nums += `<text x="${p[0]}" y="${p[1]}" text-anchor="middle" dominant-baseline="central" fill="#0B0B0C" font-size="9" font-weight="500">${h}</text>`;
  }
  const hand = (len, w, col, period, tail) => `<line x1="50" y1="${50 + tail}" x2="50" y2="${50 - len}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" style="transform-origin:50px 50px;animation:hwwspin ${period}s linear infinite;animation-delay:-${(s % period).toFixed(2)}s"/>`;
  return `<svg viewBox="0 0 100 100" style="height:100%;max-width:100%;aspect-ratio:1/1;display:block;margin:0 auto;font-family:-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Arial, sans-serif">
    <style>@keyframes hwwspin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}</style>
    ${marks}${nums}${hand(22, 3, '#0B0B0C', 43200, 0)}${hand(36, 2, '#0B0B0C', 3600, 0)}${hand(42, 0.8, '#E8590C', 60, 8)}
    <circle cx="50" cy="50" r="2.2" fill="#0B0B0C"/><circle cx="50" cy="50" r="1" fill="#E8590C"/></svg>`;
]]]

custom_fields.photo:
[[[
  const DIR = 'media-source://media_source/local/Photo Slideshow';
  window.__hwPh = window.__hwPh || {urls: {}};
  const P = window.__hwPh;
  if (!P.busy && hass && (!P.next || Date.now() >= P.next)) {
    P.busy = true;
    Promise.resolve().then(() => hass.callWS({type: 'media_source/browse_media', media_content_id: DIR}))
      .then((r) => {
        P.items = ((r && r.children) || []).filter(c => c.media_class === 'image' || /\.(jpe?g|png|webp|gif|heic)$/i.test(c.title || '')).map(c => c.media_content_id);
        P.err = P.items.length ? null : 'Nessuna foto nella cartella Photo Slideshow';
        P.next = Date.now() + (P.err ? 60000 : 600000);
      })
      .catch((e) => { P.err = (e && e.message) ? e.message : String(e); P.next = Date.now() + 60000; })
      .finally(() => { P.busy = false; });
  }
  const resolve = (id) => {
    const c = P.urls[id];
    if ((c && c.exp > Date.now()) || (P.pending && P.pending[id])) return;
    P.pending = P.pending || {};
    P.pending[id] = true;
    Promise.resolve().then(() => hass.callWS({type: 'media_source/resolve_media', media_content_id: id, expires: 86400}))
      .then((r) => { if (r && r.url) P.urls[id] = {url: r.url, exp: Date.now() + 82800000}; })
      .catch(() => {})
      .finally(() => { delete P.pending[id]; });
  };
  let url = '';
  if (P.items && P.items.length && hass) {
    const n = P.items.length, slot = Math.floor(Date.now() / 120000);
    const cur = P.items[slot % n], nxt = P.items[(slot + 1) % n];
    resolve(cur); resolve(nxt);
    const c = P.urls[cur];
    url = (c && c.exp > Date.now()) ? c.url : (P.last || '');
    if (url) P.last = url;
  }
  const box = 'position:relative;width:100%;height:100%;border-radius:28px;overflow:hidden;background:#5E6E72;box-shadow:0 8px 22px rgba(0,0,0,0.18)';
  if (!url) {
    const msg = P.err ? P.err : 'Carico le foto\u2026';
    return `<div style="${box};display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#E9EEEF;text-align:center;padding:0 20px;box-sizing:border-box"><ha-icon icon="mdi:image-outline" style="--mdc-icon-size:48px;width:48px;height:48px"></ha-icon><div style="font-size:17px;font-weight:500">${msg}</div></div>`;
  }
  return `<div style="${box}"><img src="${url}" alt="" style="width:100%;height:100%;object-fit:cover;display:block"></div>`;
]]]

