  if (!F.ev) return wrap(`<div style="font-size:17px;color:#26302F">${F.err ? 'Calendar unavailable' : 'Carico il calendario\u2026'}</div>`);
  const evs = F.ev.filter(e => pd(e.end) > now).sort((a, b) => pd(a.start) - pd(b.start)).slice(0, 3);
  if (!evs.length) return wrap(`<div style="font-size:17px;color:#26302F">Nessun impegno questa settimana</div>`);
  let out = '', lastKey = null, g = 0;
  evs.forEach(e => {
    const s = pd(e.start), key = sod(s < now ? now : s).getTime();
    if (key !== lastKey) {
      const diff = Math.round((key - today) / 86400000);
      const label = diff === 0 ? 'Oggi' : diff === 1 ? 'Domani' : new Date(key).toLocaleDateString('it-IT', {weekday: 'long'});
      out += `<div style="font-size:15px;font-weight:700;color:${g === 0 ? '#FFFFFF' : '#4A5558'};text-transform:uppercase;letter-spacing:.5px;margin-top:2px">${label}</div>`;
      lastKey = key; g++;
    }
    const allDay = typeof e.start === 'string' && e.start.length === 10;
    const time = allDay ? 'Tutto il giorno' : s.toLocaleTimeString('it-IT', {hour: 'numeric', minute: '2-digit'});
    out += `<div style="display:flex;align-items:center;gap:10px;min-width:0"><span style="width:10px;height:10px;border-radius:50%;background:${(CALS[e._cal] || {}).color || '#FFFFFF'};flex:none"></span><span style="font-size:19px;font-weight:600;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(e.summary)}</span><span style="font-size:16px;color:#26302F;flex:none">${time}</span></div>`;
  });
  return wrap(out);
]]]

