custom_fields.c:
[[[
  const d = new Date();
  const s = d.getHours() % 12 * 3600 + d.getMinutes() * 60 + d.getSeconds() + d.getMilliseconds() / 1000;
  const BG = '#4D7DB8';
  const ar = ((window.innerWidth || 1180) - 28) / ((window.innerHeight || 820) - 28);
  const W = Math.max(100, 100 * ar), cx = W / 2, cy = 50;
  const num = (t, x, y) => `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central" fill="#0B0B0C" font-size="56" font-weight="300" letter-spacing="-3">${t}</text>`;
  const spin = (period) => `transform-origin:${cx}px ${cy}px;animation:hwss ${period}s linear infinite;animation-delay:-${(s % period).toFixed(2)}s`;
  const hand = (len, w, period) => `<g style="${spin(period)}"><line x1="${cx}" y1="${cy}" x2="${cx}" y2="${cy - 6}" stroke="#FFFFFF" stroke-width="1.3" stroke-linecap="round"/><line x1="${cx}" y1="${cy - 6}" x2="${cx}" y2="${cy - len}" stroke="#FFFFFF" stroke-width="${w}" stroke-linecap="round"/></g>`;
  const wd = d.toLocaleDateString('it-IT', {weekday: 'short'}).toUpperCase();
  const dx = Math.min(36, 30 + (W - 100) * 0.15);
  return `<svg viewBox="0 0 ${W.toFixed(2)} 100" preserveAspectRatio="xMidYMid slice" style="width:100%;height:100%;display:block;font-family:-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Helvetica, Arial, sans-serif">
    <style>@keyframes hwss{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}</style>
    <rect x="0" y="0" width="${W}" height="100" fill="${BG}"/>
    ${num('12', cx, 25)}${num('9', cx - dx, 51)}${num('3', cx + dx, 51)}${num('6', cx + 2, 77)}
    <text x="5" y="94" fill="#0B0B0C" font-size="4.6" font-weight="700" letter-spacing="0.2">${wd} ${d.getDate()}</text>
    <g style="filter:drop-shadow(0 0.4px 0.8px rgba(0,0,0,0.35))">${hand(25, 3.2, 43200)}${hand(39, 3.2, 3600)}</g>
    <g style="${spin(60)}"><line x1="${cx}" y1="${cy + 8}" x2="${cx}" y2="3" stroke="#FFFFFF" stroke-width="0.45" stroke-linecap="round"/></g>
    <circle cx="${cx}" cy="${cy}" r="2.1" fill="#FFFFFF"/><circle cx="${cx}" cy="${cy}" r="0.9" fill="${BG}"/>
  </svg>`;
]]]
